"""
AUTO-GENERATED dirty prototype test MCP server.
Source: query catalog workbook. Regenerate with build_prototype_server.py
rather than hand-editing tool definitions -- hand-edit the MOCK RESPONSE
bodies in MOCKS (or replace _run_mock's body with a real query call)
instead.

Run:
    python3 catalog_prototype_server.py

Then point Claude Desktop's MCP config at this file (see SETUP.md).
"""
import json
import logging
from mcp.server.mcpserver import MCPServer

logging.basicConfig(level=logging.INFO)
logger = logging.getLogger("catalog-prototype")

server = MCPServer("loyalty-query-catalog-prototype")

MOCKS = {}
ENTRY_META = {}


def _run_mock(slug: str, arguments: dict) -> str:
    """Shared body for every generated tool function below.

    LOGGING: this line is your selection log. Every call here is one
    row for the Misselection Log tab -- (entry picked, arguments the
    model extracted). Pipe stdout/stderr to a file during testing and
    review weekly, per Phase 7 of the query catalog.
    """
    meta = ENTRY_META.get(slug, {})
    mock = MOCKS.get(slug)
    if mock is None:
        return json.dumps({"error": f"Unknown tool {slug}"})

    arguments = {k: v for k, v in arguments.items() if v is not None}
    logger.info(json.dumps({
        "event": "tool_selected",
        "entry_id": meta.get("id"),
        "entry_name": meta.get("name"),
        "entry_class": meta.get("class"),
        "arguments": arguments,
    }))

    payload = dict(mock)
    payload["_prototype_note"] = (
        "This is MOCKED data for catalog-selection testing. Replace "
        "the matching entry in MOCKS (or this function's caller) "
        "with a real query once selection tests clean for this entry."
    )
    payload["_arguments_received"] = arguments
    return json.dumps(payload, indent=2)


